#include <fastdds/dds/domain/DomainParticipantFactory.hpp>
#include <fastdds/rtps/transport/UDPv4TransportDescriptor.h>
#include <cstdlib>
#include <iostream>
#include <string>

int main(int argc, char **argv)
{
  if (argc != 2 || std::getenv("ROS_LOCALHOST_ONLY") == nullptr ||
    std::string(std::getenv("ROS_LOCALHOST_ONLY")) != "0" ||
    std::getenv("FASTRTPS_DEFAULT_PROFILES_FILE") == nullptr ||
    std::string(std::getenv("FASTRTPS_DEFAULT_PROFILES_FILE")) != argv[1] ||
    std::getenv("SKIP_DEFAULT_XML") == nullptr ||
    std::string(std::getenv("SKIP_DEFAULT_XML")) != "1")
  {
    std::cerr << "Unexpected profile environment\n";
    return 1;
  }
  auto *factory = eprosima::fastdds::dds::DomainParticipantFactory::get_instance();
  if (!factory->load_profiles()) {
    std::cerr << "Profile load failed\n";
    return 2;
  }
  const auto &transport = factory->get_default_participant_qos().transport();
  if (transport.use_builtin_transports || transport.user_transports.size() != 1) {
    std::cerr << "Unexpected default transport list\n";
    return 3;
  }
  auto udp = std::dynamic_pointer_cast<eprosima::fastdds::rtps::UDPv4TransportDescriptor>(
    transport.user_transports.front());
  if (!udp || udp->interfaceWhiteList.size() != 1 ||
    udp->interfaceWhiteList.front() != "127.0.0.1" || udp->non_blocking_send ||
    udp->sendBufferSize != 0 || udp->receiveBufferSize != 0)
  {
    std::cerr << "Unexpected UDP descriptor\n";
    return 4;
  }
  // Read factory defaults only. No create_participant, publisher or subscription.
  std::cout << "{\"participant_created\":false,\"use_builtin_transports\":false,"
    "\"user_transport_count\":1,\"transport_type\":\"UDPv4\","
    "\"interface_whitelist\":[\"127.0.0.1\"],\"non_blocking_send\":false,"
    "\"send_buffer_size\":0,\"receive_buffer_size\":0}\n";
  return 0;
}
